{"edits":[{"path":"app.py","content":"from utils import normalize_email

class UserStore:
    def __init__(self):
        self.users = {}

    def add_user(self, email: str, name: str):
        # FIX: normalize email during add as well
        key = normalize_email(email)
        self.users[key] = name

    def get_user(self, email: str):
        key = normalize_email(email)
        return self.users.get(key)
